// Data access. Live mode talks to the FastAPI backend; demo mode reads precomputed JSON from
// public/demo/ (generated by scripts/export_demo.py), so the dashboard also runs fully offline.
//
// By default the API is reached through the relative base "/api", which the Vite dev/preview server
// proxies to FastAPI (vite.config.ts). The browser then only talks to its own origin, so CORS never
// applies. Set VITE_API_URL (e.g. http://127.0.0.1:8000) to call the API directly instead.

export const API_URL: string = ((import.meta.env.VITE_API_URL as string | undefined) ?? "/api").replace(/\/$/, "");

let demo = false;
export const isDemo = () => demo;
export const setDemo = (v: boolean) => {
  demo = v;
};

// Map an API path to its demo snapshot file.
function demoPath(path: string): string {
  const clean = path.replace(/^\//, "").replace(/\?.*$/, "");
  if (clean.startsWith("results/") && clean !== "results/summary") return `demo/${clean}.json`;
  return `demo/${clean.replace(/\//g, "_")}.json`;
}

export async function getJSON<T>(path: string): Promise<T> {
  const url = demo ? demoPath(path) : `${API_URL}${path}`;
  const res = await fetch(url);
  if (!res.ok) {
    // the API explains missing data/models as {detail, hint}; show that instead of a bare status
    let msg = `${res.status} ${res.statusText} — ${url}`;
    try {
      const body = (await res.json()) as { detail?: string; hint?: string };
      if (body.hint || body.detail) msg = `${res.status}: ${body.hint ?? body.detail}`;
    } catch {
      /* not JSON */
    }
    throw new Error(msg);
  }
  return (await res.json()) as T;
}

export async function apiReachable(): Promise<boolean> {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 1500);
    const res = await fetch(`${API_URL}/health`, { signal: ctrl.signal });
    clearTimeout(t);
    // through the proxy a stopped API shows up as a 5xx from Vite, so also check the body
    return res.ok && ((await res.json()) as { status?: string }).status === "ok";
  } catch {
    return false;
  }
}

/** WebSocket URL: absolute API_URL -> ws(s)://host/..., relative "/api" -> same origin as the page. */
function wsBase(): string {
  if (/^https?:\/\//.test(API_URL)) return API_URL.replace(/^http/, "ws");
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return `${proto}//${window.location.host}${API_URL}`;
}

export const wsUrl = (subject: number, condition: string, model: string, speed: number) =>
  `${wsBase()}/stream/${subject}/${condition}?model=${encodeURIComponent(model)}&speed=${speed}`;

export const resultFileUrl = (experimentId: string, name: string) =>
  demo ? `demo/files/${experimentId}/${name}` : `${API_URL}/results/${experimentId}/files/${name}`;
